+    @Override
+    public TaskProvider<? extends Task> createTask(Project project) {
+        TaskProvider<SplitPackagesAuditTask> task = project.getTasks().register(TASK_NAME, SplitPackagesAuditTask.class);
+        task.configure(t -> {
