+                List<String> msg = new ArrayList<>();
+                msg.add("Split packages:");
+                splitPackages.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(e -> msg.add("  -" + e.getKey() + " -> " + e.getValue()));
