+        String message = "not permitted to read ";
+        if (paths.size() == 1) {
+            message += "the " + fileType + " file";
+        } else {
+            message += "one of more " + fileType + "files";
+        }
+        message += " [" + pathsToString(paths) + "]";
+        return new SslConfigException(message, cause);
+    }
+
